#### Comparison of Black-Scholes, Monte Carlo, and Binomial-Tree Pricing ####import timeimport numpy as npimport matplotlib.pyplot as pltfrom quant_finance.options.black_scholes_pricing import black_scholes_pricefrom quant_finance.options.monte_carlo_option_pricing import monte_carlo_option_pricefrom quant_finance.options.binomial_tree import EuropeanOption#parametersS_0 = 100K = 100r = 0.05T = 1.0sigma = 0.20q = 0.0option_type = "call"# 1 .Calculate the analytical Black-Scholes benchmarkstart_time = time.perf_counter()bs_price = black_scholes_price(    S=S_0,    K=K,    r=r,    T=T,    sigma=sigma,    q=q,    option_type=option_type,)bs_runtime = time.perf_counter() - start_time# 2. Calculate the Monte Carlo estimate and uncertainty measuresnsim = 100_000seed=0start_time = time.perf_counter()mc_price, mc_standard_error, mc_confidence_interval = (    monte_carlo_option_price(        S_0=S_0,        K=K,        r=r,        T=T,        sigma=sigma,        q=q,        nsim=nsim,        option_type=option_type,        alpha=0.05,        seed=seed,        return_stats=True,    ))mc_runtime = time.perf_counter() - start_time# 3. Calculate the European binomial-tree priceN = 500binomial_option = EuropeanOption(    S0=S_0,    K=K,    r=r,    T=T,    sigma=sigma,    N=N,    q=q,    option_type=option_type,)start_time = time.perf_counter()binomial_price, _ = binomial_option.price()binomial_runtime = time.perf_counter() - start_time# 4. Compare prices, absolute errors, and runtimesmc_absolute_error = abs(mc_price - bs_price)binomial_absolute_error = abs(binomial_price - bs_price)print(    f"{'Method':<20}"    f"{'Price':>12}"    f"{'Absolute error':>18}"    f"{'Runtime (s)':>15}")print("-" * 65)print(    f"{'Black-Scholes':<20}"    f"{bs_price:>12.6f}"    f"{0.0:>18.6f}"    f"{bs_runtime:>15.8f}")print(    f"{'Monte Carlo':<20}"    f"{mc_price:>12.6f}"    f"{mc_absolute_error:>18.6f}"    f"{mc_runtime:>15.8f}")print(    f"{'Binomial tree':<20}"    f"{binomial_price:>12.6f}"    f"{binomial_absolute_error:>18.6f}"    f"{binomial_runtime:>15.8f}")print("\nMonte Carlo standard error:", mc_standard_error)print("Monte Carlo 95% confidence interval:", mc_confidence_interval)# 6. Examine the convergence of Monte Carlo and the binomial treemc_simulation_counts = np.array(    [100, 500, 1_000, 5_000, 10_000, 50_000, 100_000])mc_convergence_prices = []for current_nsim in mc_simulation_counts:    current_mc_price = monte_carlo_option_price(        S_0=S_0,        K=K,        r=r,        T=T,        sigma=sigma,        q=q,        nsim=current_nsim,        option_type=option_type,        seed=0,    )    mc_convergence_prices.append(current_mc_price)mc_convergence_prices = np.array(mc_convergence_prices)mc_convergence_errors = abs(mc_convergence_prices - bs_price)binomial_step_counts = np.array(    [10, 25, 50, 100, 250, 500])binomial_convergence_prices = []for current_N in binomial_step_counts:    current_binomial_option = EuropeanOption(        S0=S_0,        K=K,        r=r,        T=T,        sigma=sigma,        N=current_N,        q=q,        option_type=option_type,    )    current_binomial_price, _ = current_binomial_option.price()    binomial_convergence_prices.append(current_binomial_price)binomial_convergence_prices = np.array(binomial_convergence_prices)binomial_convergence_errors = abs(    binomial_convergence_prices - bs_price)# Plot convergencefig, axes = plt.subplots(2, 2, figsize=(12, 8))axes[0, 0].plot(    mc_simulation_counts,    mc_convergence_prices,    marker="o",    label="Monte Carlo",)axes[0, 0].axhline(    bs_price,    color="black",    linestyle="--",    label="Black-Scholes",)axes[0, 0].set_xscale("log")axes[0, 0].set_title("Monte Carlo price convergence")axes[0, 0].set_xlabel("Number of simulations")axes[0, 0].set_ylabel("Option price")axes[0, 0].grid(True)axes[0, 0].legend()axes[0, 1].plot(    mc_simulation_counts,    mc_convergence_errors,    marker="o",)axes[0, 1].set_xscale("log")axes[0, 1].set_yscale("log")axes[0, 1].set_title("Monte Carlo absolute error")axes[0, 1].set_xlabel("Number of simulations")axes[0, 1].set_ylabel("Absolute error")axes[0, 1].grid(True)axes[1, 0].plot(    binomial_step_counts,    binomial_convergence_prices,    marker="o",    label="Binomial tree",)axes[1, 0].axhline(    bs_price,    color="black",    linestyle="--",    label="Black-Scholes",)axes[1, 0].set_xscale("log")axes[1, 0].set_title("Binomial-tree price convergence")axes[1, 0].set_xlabel("Number of time steps")axes[1, 0].set_ylabel("Option price")axes[1, 0].grid(True)axes[1, 0].legend()axes[1, 1].plot(    binomial_step_counts,    binomial_convergence_errors,    marker="o",)axes[1, 1].set_xscale("log")axes[1, 1].set_yscale("log")axes[1, 1].set_title("Binomial-tree absolute error")axes[1, 1].set_xlabel("Number of time steps")axes[1, 1].set_ylabel("Absolute error")axes[1, 1].grid(True)plt.tight_layout()plt.show()# 6. Summarize when each pricing method is appropriateprint(    """Method suitability-------------------Black-Scholes:- Best for standard European call and put options.- Extremely fast, deterministic, and useful as an analytical benchmark.- Limited by its restrictive assumptions and cannot directly model early exercise  or path-dependent payoffs.Monte Carlo:- Best for complex, path-dependent, or high-dimensional derivatives.- Flexible and provides statistical uncertainty measures.- Converges slowly at approximately O(1 / sqrt(nsim)) and is inefficient for  simple European options when an analytical solution exists.- Standard Monte Carlo is not directly suited to early-exercise options.Binomial tree:- Best for European, American, and Bermudan options in low-dimensional settings.- Handles early exercise naturally through backward induction.- Deterministic and intuitive, but computational cost increases with the number  of time steps and becomes problematic in higher dimensions.""")